pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testRegression_property() public {
        vm.deal(address(this), 10 ether);
        vm.startPrank(address(this));
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();
        vm.stopPrank();

        address user = address(0x1);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.Deposit{value: 1 wei}();

        vm.prank(user);
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1));

        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
